-- Bulk import of the full Haitian-plant list (372 entries) from
-- medikaplant.org / TRAMIL. Existing letter-A rows (with editorial notes and
-- corrected names) are preserved via ON CONFLICT DO NOTHING. New rows are
-- provisional (status 'pwovizwa', tramil 'pa-jwenn') until reviewed.
insert into public.glossary_terms
  (code, letter, name, variants, family, scientific_name, tramil, status, active, display_order)
select
  x->>'code', x->>'letter', x->>'name',
  coalesce((select array_agg(v) from jsonb_array_elements_text(x->'variants') v), '{}'),
  nullif(x->>'family',''), nullif(x->>'scientific',''),
  'pa-jwenn', 'pwovizwa', true, 0
from jsonb_array_elements($json$
